antiPatterns.code:
// Avoid: Putting complex UI inside message content
<Message message={{ 
  role: 'assistant', 
  content: '<div>Complex HTML</div>' 
}} />

// Prefer: Use separate components for complex content
<Message message={{ role: 'assistant', content: 'Here is the data:' }} />
<DataDisplay data={...} />

// Avoid: Hardcoded message
<Message message={{ id: '1', role: 'user', content: 'Fixed text' }} />

// Prefer: Dynamic message from state
<Message message={messages[currentIndex]} />

compositionRules.example:
const handleSubmit = (text) => {
  const newMessage = { id: Date.now(), role: 'user', content: text };
  setMessages([...messages, newMessage]);
}
